<?php defined('AFAQ') || exit; $info = array_filter([['Location', $p['location']], ['Client', $p['client']], ['Category', $p['category']], ['Status', STATUSES[$p['status']] ?? ''], ['Started', month_label($p['start_date'])], ['Completed', month_label($p['end_date'])]], function ($r) { return $r[1] !== '' && $r[1] !== null; }); ?>
<section class="proj-hero"><div class="media ph r-21-9"><?php if ($p['image']): ?><img src="<?= h(img($p['image'])) ?>" alt="<?= h($p['name']) ?>"><?php endif; ?></div></section>
<section class="section"><div class="container stack gap12"><div class="stack gap4"><a href="/projects" class="small">← All projects</a><span class="eyebrow"><?= h($p['category'] ?: 'Project') ?></span><h1 class="h1"><?= h($p['name']) ?></h1></div>
<div class="detail-grid"><dl class="info-list"><?php foreach ($info as $r): ?><div><dt class="caption"><?= h($r[0]) ?></dt><dd><?= h($r[1]) ?></dd></div><?php endforeach; ?></dl>
<div class="stack gap6 prose"><?= paras($p['description']) ?><?php if ($p['scope']): ?><h2 class="h3">Scope of work</h2><?= paras($p['scope']) ?><?php endif; ?><?php if ($p['video'] && preg_match('#^https?://#i', $p['video'])): ?><div><a class="btn btn-outline" href="<?= h($p['video']) ?>" target="_blank" rel="noopener noreferrer">Watch project video</a></div><?php endif; ?></div></div>
<?php if ($gal): ?><div class="stack gap6"><h2 class="h2">Gallery</h2><div class="grid grid-3" data-gallery><?php foreach ($gal as $i => $g): ?><button type="button" class="media r-3-2 gal-btn" data-src="<?= h(img($g)) ?>" aria-label="Open image <?= $i + 1 ?> of <?= count($gal) ?>"><img src="<?= h(img($g)) ?>" alt="<?= h($p['name']) ?> photo <?= $i + 1 ?>" loading="lazy"></button><?php endforeach; ?></div></div><?php endif; ?>
<?php if ($rel): ?><div class="stack gap6"><h2 class="h2">Related projects</h2><div class="grid grid-3"><?php foreach ($rel as $p) { $large = false; include ROOT . '/app/views/card.php'; } ?></div></div><?php endif; ?>
<div class="cta-row bandbox"><h2 class="h2">Planning something similar?</h2><a href="/contact" class="btn btn-primary"><?= h($S['cta_text']) ?></a></div></div></section>
